package com.sistemahospitalar.hospital.controller; import com.sistemahospitalar.hospital.model.Internacao; import com.sistemahospitalar.hospital.service.InternacaoService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/internacoes") public class InternacaoController {private final InternacaoService service; public InternacaoController(InternacaoService s){service=s;} @GetMapping public List<Internacao> listar(){return service.listar();} @PostMapping public ResponseEntity<Internacao> criar(@Valid @RequestBody Internacao i){return ResponseEntity.status(HttpStatus.CREATED).body(service.salvar(i));} }
